'use client';
import { useState } from 'react';
import { Edit, Trash2, Plus, GripVertical } from 'lucide-react';

export default function MenuPage() {
    const [items] = useState([
        { id: 1, name: 'Chicken Biryani', price: 240, veg: false, available: true },
        { id: 2, name: 'Paneer Tikka', price: 180, veg: true, available: true },
        { id: 3, name: 'Butter Naan', price: 40, veg: true, available: false },
    ]);

    return (
        <div className="p-4 space-y-4">
            <div className="flex justify-between items-center">
                <h1 className="text-2xl font-bold text-gray-900">Menu</h1>
                <button className="bg-black text-white p-2 rounded-lg">
                    <Plus size={20} />
                </button>
            </div>

            <div className="space-y-3">
                {items.map((item) => (
                    <div key={item.id} className={`bg-white p-3 rounded-xl border ${item.available ? 'border-gray-200' : 'border-gray-100 bg-gray-50'} shadow-sm flex items-center gap-3`}>
                        <GripVertical size={20} className="text-gray-300" />

                        <div className="flex-1">
                            <div className="flex items-center gap-2">
                                <div className={`w-4 h-4 border ${item.veg ? 'border-green-600' : 'border-red-600'} flex items-center justify-center`}>
                                    <div className={`w-2 h-2 rounded-full ${item.veg ? 'bg-green-600' : 'bg-red-600'}`} />
                                </div>
                                <span className={`font-bold ${!item.available && 'text-gray-400 line-through'}`}>{item.name}</span>
                            </div>
                            <p className="text-sm text-gray-500 font-medium">₹{item.price}</p>
                        </div>

                        <div className="flex items-center gap-2">
                            <label className="relative inline-flex items-center cursor-pointer">
                                <input type="checkbox" checked={item.available} readOnly className="sr-only peer" />
                                <div className="w-9 h-5 bg-gray-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked:bg-green-500"></div>
                            </label>
                            <button className="p-2 text-gray-400 hover:text-blue-500"><Edit size={18} /></button>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
}
